import type { ClaimCategory, ClaimRecord } from "./types";
import medguidesJson from "./data/medguides.json";
import { PI_SUFFIX } from "./medguide-claims";

/**
 * Statements about OTHER medicines (interactions) and the conditions that rule a medicine out, for the medicines
 * that have a stored Medication Guide. Each rests on one short exact passage of the prescribing information of
 * the same US label (stored beside the Medication Guide, see scripts/evidence/pi-sections.ts) and restates it in
 * plain words. The restatement adds no dose, number, warning or condition the passage lacks.
 *
 * A list of example medicines in a label is a list of examples. It is not an exhaustive interaction check, and a
 * medicine missing from it is not shown to be free of interactions. Every statement says so.
 *
 * US labels only. None is an Indian label. None has been reviewed.
 */
const SETID = new Map((medguidesJson as unknown as { slug: string; setid?: string }[]).filter((r) => r.setid).map((r) => [r.slug, r.setid!]));

const LIMITS = [
  "US prescribing information, which is written for clinicians: this restates one passage of it in plain words.",
  "The label gives examples. It is not a complete list of interacting medicines, and a medicine that is not named is not shown to be free of interactions.",
  "US label only: Indian approval, strengths and warnings may differ.",
];

const LIMITS_ADVICE = [
  "US prescribing information (the part that tells clinicians what to counsel patients about): this restates one passage of it in plain words.",
  "It is not a complete list of signs that need help. A sign that is not listed is not shown to be harmless, and when in doubt you should contact your pharmacist or prescriber.",
  "US label only: Indian approval, strengths and warnings may differ. Any phone number or service it names is a US one.",
];

export type InteractionClaim = [slug: string, category: ClaimCategory, loinc: string, passage: string, wording: string];

const counters = new Map<string, number>();
function build([slug, category, loinc, passage, wording]: InteractionClaim): ClaimRecord {
  const setid = SETID.get(slug);
  if (!setid) throw new Error(`no stored Medication Guide label for ${slug}`);
  const key = `${slug}:${category}`;
  const n = (counters.get(key) ?? 0) + 1;
  counters.set(key, n);
  return {
    id: `${key}:pi${n}`,
    slug,
    category,
    patientWording: wording,
    wordingKind: "paraphrase",
    sourceId: `${slug}:us-product-label:${setid}${PI_SUFFIX}`,
    excerptId: `${slug}:pi:${loinc}`,
    passage,
    applicability: ["Adults, as described in the US prescribing information for the named product."],
    limitations: category === "urgent-help" || category === "how-to-take" ? LIMITS_ADVICE : LIMITS,
    verification: "passage-found-in-source",
    review: "not-reviewed",
    openQuestions: ["Compare with the Indian product information for the brand the patient is actually given."],
  };
}

